recs=[]
recs.append(R(9635628,"بیک کیے ہوئے ویگن گلیزڈ ڈونٹس",
"میٹھے، نم اور ناقابلِ یقین حد تک لذیذ ویگن گلیزڈ ڈونٹس جو بہترین مزے کے لیے بیک کیے گئے ہیں (تلے ہوئے نہیں!)۔",
"12 ڈونٹس","1 سرونگ",
[("خشک اجزاء","240 گرام ثابت گندم کا پیسٹری آٹا، تقریباً 2 کپ"),("خشک اجزاء","2 چائے کے چمچ بیکنگ پاؤڈر"),("خشک اجزاء","1 چائے کا چمچ دار چینی"),("گیلے اجزاء","½ کپ بغیر میٹھا کیا ہوا سیب کی پیوری (ایپل ساس)"),("گیلے اجزاء","½ کپ میپل سیرپ"),("گیلے اجزاء","½ کپ سویا دودھ یا کوئی اور غیر ڈیری دودھ"),("گیلے اجزاء","2 چائے کے چمچ خالص ونیلا ایکسٹریکٹ"),
("گلیز کے لیے","¾ کپ پاؤڈر شوگر"),("گلیز کے لیے","2 چائے کے چمچ لیموں کا رس"),("گلیز کے لیے","1-2 کھانے کے چمچ سویا دودھ یا کوئی اور ڈیری سے پاک دودھ")],
["اوون کو 350℉/176℃ پر پہلے سے گرم کریں اور 12 ڈونٹس بنانے کے لیے کافی ڈونٹ پینز لے لیں۔ (میں 6-6 ڈونٹس کے 2 پینز استعمال کرتی ہوں۔)",
"ایک درمیانے مکسنگ پیالے میں آٹا، بیکنگ پاؤڈر اور دار چینی پھینٹ کر ملا لیں۔ پھر گیلے اجزاء ڈالیں اور ملنے تک ہلائیں۔",
"ڈونٹ کا آمیزہ 12 ڈونٹ ٹنز میں تقسیم کریں اور 12-15 منٹ بیک کریں۔ ڈونٹس اس وقت تیار ہیں جب چھونے پر سخت ہوں، لیکن آہستگی سے دبانے پر ذرا دب جائیں۔ اوون سے نکالیں اور گلیز لگانے سے پہلے ٹھنڈا ہونے دیں۔",
"جب ڈونٹس ٹھنڈے ہو رہے ہوں، گلیز تیار کریں۔ چینی، لیموں کا رس اور دودھ (1 کھانے کے چمچ سے شروع کر کے) ایک چھوٹے پیالے میں ملائیں۔ ضرورت ہو تو تھوڑا اور دودھ ڈالیں۔",
"ٹھنڈا ہو جانے پر ہر ڈونٹ کے اوپری حصے کو گلیز میں ڈبوئیں، اور انہیں گلیز والا رخ اوپر کر کے وائر ریک پر رکھیں تاکہ گلیز جم جائے۔ لطف اٹھائیں!"],
["سب سے درست نتائج کے لیے کچن اسکیل سے اپنا آٹا تولیں۔ تھیلے سے آٹا چمچ بھر کر لینے سے ہو سکتا ہے بہت زیادہ آٹا استعمال ہو جائے اور بناوٹ بدل جائے۔","تازہ اور فعال بیکنگ پاؤڈر استعمال کریں۔ کھولنے کے بعد بیکنگ پاؤڈر اپنی تاثیر کھونا شروع کر دیتا ہے، اس لیے بہتر ہے کہ اپنا بیکنگ پاؤڈر 6 ماہ کے اندر استعمال کر لیں۔","ڈونٹس کو پین سے نکالنے کی کوشش کرنے سے پہلے انہیں 10-15 منٹ ٹھنڈا ہونے دیں۔ اگر ڈونٹس بہت گرم ہوں تو ان کے ٹوٹنے کا خطرہ ہے۔","وائر ریک پر منتقل کرنے کے بعد، گلیز لگانے سے پہلے انہیں کمرے کے درجہ حرارت تک ٹھنڈا ہوتے رہنے دیں۔","اوپر دی گئی غذائی معلومات میں گلیز کے ساتھ 1 ڈونٹ شامل ہے۔"],[]))
recs.append(R(9644787,"میٹھے سنگترے کی گلیز کے ساتھ ویگن کرین بیری اورنج بریڈ",
"ایک صحت مند ویگن کرین بیری اورنج بریڈ جو نم، قدرتی طور پر میٹھی اور صحت بخش اجزاء سے بنی ہے",
"12 قتلے (1 - 5\"x9\" لوف پین)","1 سرونگ",
[("خشک اجزاء","2 کپ اوٹ کا آٹا، پسند ہو تو گلوٹن سے پاک"),("خشک اجزاء","2.5 چائے کے چمچ بیکنگ پاؤڈر"),("خشک اجزاء","½ چائے کا چمچ بیکنگ سوڈا"),("خشک اجزاء","1 چائے کا چمچ دار چینی"),
("گیلے اجزاء","1 کپ گٹھلی نکالی ہوئی کھجوریں"),("گیلے اجزاء","1.5 کپ پانی"),("گیلے اجزاء","½ کپ (اور گلیز کے لیے 2 کھانے کے چمچ، الگ رکھیں) سنگترے کا رس، تقریباً 1 بڑے سنگترے سے تازہ نچوڑا ہوا"),("گیلے اجزاء","1 کھانے کا چمچ سنگترے کا چھلکا (کدوکش کیا ہوا)"),("گیلے اجزاء","⅓ کپ بغیر میٹھا کیا ہوا سیب کی پیوری (ایپل ساس)"),("گیلے اجزاء","1 کپ تازہ کرین بیریز یا تازہ بلیو بیریز اگر آپ کے علاقے میں تازہ کرین بیریز دستیاب نہ ہوں")],
["اوون کو 350 ڈگری F پر پہلے سے گرم کریں اور 9\" x 5\" (یا اسی طرح کے) لوف پین میں پارچمنٹ پیپر بچھا دیں۔",
"ایک بڑے مکسنگ پیالے میں اپنے تمام خشک اجزاء ملائیں اور پھینٹ لیں۔ الگ رکھ دیں۔",
"گٹھلی نکالی ہوئی کھجوریں اور پانی بلینڈر میں ڈالیں اور بالکل ہموار ہونے تک پروسیس کریں۔ اس سے تقریباً 2 کپ کھجور کا سیرپ بنے گا۔ 1.5 کپ کی مقدار ناپ لیں جو آپ کی لوف میں استعمال ہوگی اور باقی 1/2 کپ بعد میں گلیز بنانے کے لیے استعمال ہوگا۔ لوف میں 1.5 کپ سے زیادہ استعمال نہ کریں۔",
"اب اپنے گیلے اجزاء (کرین بیریز کے علاوہ) خشک اجزاء والے پیالے میں ڈالیں: آپ کے بنائے ہوئے کھجور کے سیرپ کا 1.5 کپ، 1/2 کپ سنگترے کا رس، سنگترے کا چھلکا، اور ایپل ساس۔ ملنے تک ملائیں اور پھر کرین بیریز آہستگی سے ملا دیں۔",
"آمیزہ اپنے تیار لوف پین میں ڈالیں اور لوف پین کو سخت سطح پر 2-3 بار آہستگی سے ٹھونکیں تاکہ یقینی ہو کہ بریڈ میں کوئی خالی جگہ نہ رہے۔ اسپیچولا سے نہ دبائیں۔",
"اپنے پہلے سے گرم اوون میں 45-55 منٹ بیک کریں، جب تک بیچ میں ڈالی گئی ٹوتھ پک خشک نکلے۔ آپ کے اوون اور لوف پین کے سائز کے لحاظ سے پکانے کا وقت مختلف ہوگا۔ بیک ہو جانے پر اوون سے نکالیں اور بریڈ کو پین سے نکالنے سے پہلے 10 منٹ ٹھنڈا ہونے دیں۔ گلیز لگانے سے پہلے مکمل ٹھنڈا ہونے کے لیے کولنگ ریک پر منتقل کریں۔",
"اپنی گلیز بنانے کے لیے: اپنے باقی 1/2 کپ کھجور کے سیرپ میں 2 کھانے کے چمچ تازہ نچوڑا ہوا سنگترے کا رس ملائیں اور اچھی طرح ہلائیں۔ پھر گلیز کو اپنی ٹھنڈی لوف پر ڈالیں۔ قتلے کاٹیں اور لطف اٹھائیں!"],
["اگر آپ کے پاس طاقتور بلینڈر نہیں ہے تو پہلے اپنی کھجوروں کو تقریباً 15 منٹ نیم گرم پانی میں بھگو دیں۔ پھر پانی نکالیں اور ہدایت کے مطابق کھجور کا سیرپ بنائیں۔ اس سے کھجوریں نرم ہو جائیں گی اور بلینڈ کرنا آسان ہوگا۔ تازہ اور فعال بیکنگ پاؤڈر استعمال کریں۔ جو بیکنگ پاؤڈر 6+ ماہ سے آپ کی الماری میں کھلا ہو وہ اپنی تاثیر کھونا شروع کر سکتا ہے۔ یقینی بنائیں کہ آپ کی کرین بیری اورنج بریڈ گلیز لگانے سے پہلے مکمل ٹھنڈی ہو۔ اگر آپ کے علاقے میں تازہ کرین بیریز دستیاب نہیں ہیں تو تازہ بلیو بیریز بھی اس میٹھی بریڈ میں بہت اچھی لگتی ہیں۔ بریڈ ڈھکی ہوئی کمرے کے درجہ حرارت پر 2-3 دن رہے گی، یا ہوا بند ڈبے میں 3-4 ہفتے تک منجمد کریں۔"],[]))
recs.append(R(9652525,"ویگن ایووکاڈو میکرونی اینڈ چیز",
"ایک بھرپور اور کریمی ڈش جو بچوں اور بڑوں دونوں کو پسند ہے! یہ ایووکاڈو میک بنانا آسان، چھپی ہوئی صحت بخش اور شاندار لذیذ ہے!",
"6 سرونگ","1 سرونگ",
["¼ کپ کچے کاجو","1 بڑا پکا ہوا ایووکاڈو، چھلکا اور گٹھلی ہٹائی ہوئی","1.5 کپ بغیر میٹھا کیا ہوا کاجو کا دودھ یا اپنی پسند کا پودوں سے بنا دودھ","3 کھانے کے چمچ لیموں کا رس، تقریباً 1 چھوٹا لیموں یا آدھا بڑا","¼ کپ نیوٹریشنل ییسٹ","1.5 چائے کے چمچ سمندری نمک","1 چائے کا چمچ لہسن پاؤڈر","1 چائے کا چمچ سموکڈ پاپریکا","1 کھانے کا چمچ ویگن مکھن یا ایووکاڈو کا تیل، اختیاری","450 گرام میکرونی پاستا، پسند ہو تو گلوٹن سے پاک",
("اختیاری سجاوٹ","ویگن پارمیزن پنیر، بہت زیادہ تجویز کردہ"),("اختیاری سجاوٹ","ایووکاڈو کے قتلے"),("اختیاری سجاوٹ","تازہ اجمودا، چائیوز یا سویا (ڈل)")],
["ایک بڑے برتن میں نمکین پانی ابال لائیں، اور پاستا کو ال دینتے کے لیے پیکٹ کی ہدایات کے مطابق پکائیں۔ پانی نکال کر برتن میں واپس ڈال دیں।".replace("।","۔"),
"اس دوران پاستا کے علاوہ اپنے تمام اجزاء ہائی اسپیڈ بلینڈر میں ڈالیں اور ہموار ہونے تک پروسیس کریں۔ ساس اپنے پاستا پر ڈالیں اور اچھی طرح ملائیں۔",
"اپنی پسند کی سجاوٹ کے ساتھ پیش کریں اور لطف اٹھائیں۔"],
["اگر آپ کے پاس ہائی اسپیڈ بلینڈر نہیں ہے تو پہلے اپنے کاجو بھگونا یقینی بنائیں۔ 30 منٹ کھولتے ہوئے گرم پانی میں بھگوئیں، پھر پانی نکال کر ہدایت کے مطابق استعمال کریں۔ بہترین نتائج کے لیے پاستا پکانے کے پانی میں نمک ڈالیں۔ اپنے پاستا کو زیادہ نہ پکائیں۔ ال دینتے کے لیے پیکٹ کی ہدایات کے مطابق پکائیں۔ پاستا تھوڑے سخت پن کے ساتھ سب سے اچھا لگتا ہے، حد سے زیادہ نرم نہیں۔ بچا ہوا فریج میں 2-3 دن تک رہتا ہے۔ دوبارہ گرم کرنے کے لیے پاستا کے ساتھ اسکیلیٹ میں کچھ پودوں سے بنا دودھ، پانی یا شوربہ ڈالیں، تاکہ دوبارہ نم ہو جائے اور اندر تک گرم ہو جائے۔"],[]))
recs.append(R(9655561,"ویگن بلیو بیری پائی [زیادہ تر سے زیادہ صحت مند!]",
"یہ ویگن بلیو بیری پائی تازہ اور میٹھی ہے اور ہلکی سی کھٹاس کے ساتھ۔ آپ کی روایتی پائی کا ایک صحت مند انداز، کم چینی کے ساتھ، بغیر تیل یا مکھن کے، اور ثابت گندم کی کرسٹ کے ساتھ!",
"8 قتلے","1 سرونگ",
["2 ویگن بغیر تیل کی پائی کرسٹس یا اپنی پسند کی پائی کرسٹ","5.5 کپ بلیو بیریز","⅓ کپ غیر ریفائنڈ ناریل کی چینی یا اپنی پسند کی دانے دار چینی","¼ کپ کارن اسٹارچ یا ٹیپیوکا آٹا","2 کھانے کے چمچ لیموں کا رس، تقریباً 1 درمیانا لیموں","1 چائے کا چمچ دار چینی، اختیاری، لیکن تجویز کردہ","1-2 کھانے کے چمچ بغیر میٹھا کیا ہوا کاجو کا دودھ یا اپنی پسند کا پودوں سے بنا دودھ","1-2 کھانے کے چمچ سفید چینی، اوپر چھڑکنے کے لیے اختیاری"],
["اپنی پسند کی پائی کرسٹ تیار کریں اور اس کی ہدایات کے مطابق بلائنڈ بیک کریں۔ اگر آپ میری بغیر تیل کی پائی کرسٹ استعمال کر رہے ہیں تو 1 کرسٹ 15 منٹ بیک کریں، جب تک کنارے سنہری نہ ہو جائیں۔ پھر اوون سے نکال کر الگ رکھ دیں۔ دوسری پائی کرسٹ کو بیل کر الگ رکھ دیں تاکہ بھرائی کے بعد اپنی پائی کے اوپر رکھی جا سکے۔",
"اوون کو 350 ڈگری F پر پہلے سے گرم کریں۔",
"ایک مکسنگ پیالے میں بلیو بیریز، چینی، کارن اسٹارچ، لیموں کا رس اور دار چینی ملائیں۔ اچھی طرح ہلائیں۔ پھر آمیزہ اپنی تیار پائی کرسٹ میں ڈال دیں۔",
"اب دوسری پائی کرسٹ سے بھرائی کو ڈھانپ دیں۔ آپ پوری کرسٹ اوپر رکھ کر کناروں کو موڑ سکتے ہیں، اور اپنی کرسٹ کے بیچ میں بھاپ نکلنے کے سوراخ بنا سکتے ہیں۔ متبادل کے طور پر، آپ پائی کو ڈھانپنے کے لیے ٹوکری کی بنت کا نمونہ یا ستارے کی شکل (یا کوئی بھی شکل) کے کٹ آؤٹس بنا سکتے ہیں۔ آپ کی مرضی۔",
"اپنی اوپری کرسٹ پر اپنی پسند کا پودوں سے بنا دودھ لگائیں اور اگر چاہیں تو اوپر چینی چھڑک سکتے ہیں۔",
"اپنی پائی کو 45-55 منٹ بیک کریں، جب تک بلیو بیریز کا رس بلبلے نہ بنانے لگے اور کرسٹ سنہری نہ ہو جائے۔ اگر آپ کی پائی بہت جلدی پک رہی ہو تو اوپر کو پائی شیلڈ سے ڈھانپیں یا ایلومینیم فوائل استعمال کریں تاکہ وہ بہت گہری نہ ہو جائے۔",
"اوون سے نکالیں اور کاٹنے اور پیش کرنے سے پہلے مکمل ٹھنڈا ہونے دیں۔ پائی کو مکمل جمنے کے لیے ٹھنڈا ہونا ضروری ہے۔"],
["اگر آپ کی کرسٹ بہت جلدی پک رہی ہو تو کرسٹ کو زیادہ پکنے سے بچانے کے لیے اسے پائی شیلڈ یا ایلومینیم فوائل سے ڈھانپ دیں۔ اگر اوپر کے لیے پوری پائی کرسٹ استعمال کر رہے ہیں تو بھاپ نکلنے کے سوراخ بنانا یقینی بنائیں! اگر ٹوکری کی بنت کا نمونہ بنا رہے ہیں یا ستارے کے کٹ آؤٹس استعمال کر رہے ہیں تو سوراخوں کی ضرورت نہیں۔ اپنی بلیو بیری پائی کو کاٹنے سے پہلے مکمل ٹھنڈا ہونے دیں! ٹھنڈا ہونے کا وقت آپ کی پائی کے اچھی طرح جمنے کے لیے انتہائی اہم ہے۔ اگرچہ آپ گرم ہوتے ہوئے بھی کاٹ سکتے ہیں، ٹھنڈا ہونے تک وہ بہتی رہے گی۔ بچی ہوئی پائی 3-4 دن فریج میں رکھی جا سکتی ہے، یا ہوا بند کر کے 2 ماہ تک منجمد کی جا سکتی ہے۔ غذائی معلومات میں 2 مکمل بغیر تیل کی پائی کرسٹس شامل ہیں۔ اگر کوئی اور کرسٹ استعمال کر رہے ہیں، اوپری کرسٹ چھوڑ رہے ہیں، یا ستارے کے کٹ آؤٹس استعمال کر رہے ہیں تو غذائی معلومات مختلف ہوں گی۔"],[]))
