recs.append(R(9660403,"ویگن ہیم [سیٹان ہیم]",
"گوشت جیسا، نرم، ناقابلِ یقین حد تک ذائقے دار ویگن ہیم جس پر دھوئیں دار میپل گلیز لگی ہے!!",
"8 سرونگ","1 سرونگ",
[(HM,"1 کپ چنے، ڈبے والے یا پکے ہوئے (پانی نکالے ہوئے)"),(HM,"1 کپ سبزیوں کا شوربہ، نمکین/ذائقے دار شوربہ استعمال کریں جیسے میرا گھر کا بنا ہوا"),(HM,"3-4 جوّے لہسن"),(HM,"3 کھانے کے چمچ ٹماٹر کا پیسٹ"),(HM,"2 کھانے کے چمچ ایووکاڈو کا تیل یا اپنی پسند کا کھانا پکانے کا تیل (بغیر تیل کے لیے تیل کی جگہ مزید شوربہ ڈالیں)"),(HM,"2 چائے کے چمچ لکوئڈ اسموک"),(HM,"1.5 کھانے کے چمچ سموکڈ پاپریکا"),(HM,"1 چائے کا چمچ سمندری نمک"),(HM,"¼ چائے کا چمچ دار چینی"),(HM,"¼ چائے کا چمچ پسے ہوئے لونگ"),(HM,"210 گرام وائٹل ویٹ گلوٹن، تقریباً 1.75 کپ"),
(MG,"½ کپ سبزیوں کا شوربہ، نمکین/ذائقے دار شوربہ استعمال کریں جیسے میرا گھر کا بنا ہوا"),(MG,"3 کھانے کے چمچ میپل سیرپ"),(MG,"2 چائے کے چمچ سموکڈ پاپریکا"),(MG,"1 چائے کا چمچ پیلی رائی (یلو مسٹرڈ)")],
["وائٹل ویٹ گلوٹن کے علاوہ ہیم کے تمام اجزاء فوڈ پروسیسر میں ڈالیں اور زیادہ تر ملنے تک پروسیس کریں۔ پھر وائٹل ویٹ گلوٹن کا آدھا حصہ ڈالیں اور ملنے تک پروسیس کرتے رہیں۔ اب باقی آدھا ڈالیں اور زیادہ تر ملنے تک پروسیس کریں۔",
"آمیزہ صاف سطح پر منتقل کریں اور 1-2 منٹ ہاتھ سے گوندھیں، آگے بڑھتے ہوئے اپنے آمیزے کو مروڑتے اور گرہ لگاتے رہیں۔ پھر اسے جتنا ممکن ہو یکساں بیضوی شکل دیں، لیکن اس کا بالکل درست ہونا ضروری نہیں۔ (بصری رہنمائی کے لیے اوپر طریقے کی تصاویر دیکھیں۔)",
"اپنے روسٹ کو چیز کلاتھ (یا پارچمنٹ اور ایلومینیم فوائل) سے مضبوطی سے لپیٹیں اور سروں کو محفوظ کریں۔",
"اپنے انسٹنٹ پاٹ کی تہہ میں 1.5 کپ پانی ڈالیں اور اس کا ٹریوٹ اندر رکھیں۔ پھر اپنا لپیٹا ہوا ہیم ٹریوٹ کے اوپر رکھیں۔ ڈھکن بند کریں اور یقینی بنائیں کہ والو سیلنگ کی پوزیشن میں ہو۔ 40 منٹ کے لیے اسٹیم فنکشن پر سیٹ کریں اور پریشر کو قدرتی طور پر ریلیز ہونے دیں جب تک پن نہ گر جائے۔ پن گرنے میں تقریباً 10 منٹ لگیں گے۔",
"جب ہیم آپ کے انسٹنٹ پاٹ میں بھاپ لے رہا ہو، اپنے اوون کو 375 ڈگری F پر پہلے سے گرم کریں۔ پھر گلیز کے تمام اجزاء ایک چھوٹے مکسنگ پیالے میں ڈالیں اور ملانے کے لیے پھینٹ لیں۔ الگ رکھ دیں۔",
"روسٹ کو کٹنگ بورڈ پر منتقل کریں اور تیز چھری سے اپنے ہیم پر کٹ لگائیں۔ ایک سرے سے شروع کریں اور تقریباً 1/4-1/3 انچ گہرے اور تقریباً 1 انچ کے فاصلے پر کٹ لگائیں۔ پھر ہیم کو گھمائیں اور ایک طرف سے دوسری طرف ترچھا دہرائیں۔ (بصری رہنمائی کے لیے اوپر طریقے کی تصاویر دیکھیں۔)",
"کٹ لگا ہوا ہیم اوون میں رکھنے کے قابل ڈش میں رکھیں اور اوپر اپنی میپل گلیز ڈالیں، سلیکون برش سے یقینی بنائیں کہ آپ کے ہیم کی سطح مکمل طور پر گلیز سے ڈھک جائے۔",
"بغیر ڈھکن کے 15-20 منٹ بیک کریں، ہر چند منٹ بعد گلیز لگاتے رہیں۔ پھر اختیاری طور پر اوپر کو ہلکا بھورا کرنے کے لیے ہیم کو 2-3 منٹ بروئل کر سکتے ہیں، لیکن پسند ہو تو یہ مرحلہ چھوڑ سکتے ہیں۔",
"اوون سے نکالیں اور 5-10 منٹ آرام کرنے دیں۔ پھر آرے دار چھری یا الیکٹرک چھری سے قتلے کاٹیں۔ پیش کریں اور لطف اٹھائیں۔"],
["گھبرائیں نہیں! یہ دکھنے سے بہت زیادہ آسان ہے۔ 🙂 بہترین نتائج کے لیے اچھے معیار اور بہت ذائقے دار شوربے کا استعمال یقینی بنائیں۔ میں یہ گھر کا بنا شوربہ استعمال کرتی ہوں اور مجھے پسند ہے، لیکن دکان سے خریدا ہوا بھی چلتا ہے۔ اپنے ویگن ہیم کو لپیٹنے کے لیے چیز کلاتھ پارچمنٹ اور ایلومینیم فوائل سے زیادہ آسان ہے۔ مزید یہ کہ اگر آپ فوائل سے بچنا چاہتے ہیں تو یہ کھانے کے لیے محفوظ ہے۔ قتلے کاٹنے سے پہلے اپنے ہیم کو تھوڑا وقت آرام کرنے دیں۔ جیسے جیسے یہ ٹھنڈا ہونا شروع ہوتا ہے، یہ مزید جم جاتا ہے اور قتلے کاٹنا آسان بناتا ہے اور پتلے قتلوں کی اجازت دیتا ہے۔ بچا ہوا بند ڈبے میں فریج میں 5 دن تک رہتا ہے۔ آپ بچا ہوا، ثابت یا قتلوں کی شکل میں، زپ ٹاپ بیگ یا فریزر کے لیے موزوں ڈبے میں 3 ماہ تک منجمد کر سکتے ہیں۔"],[]))
